from PIL import Image

def convert_color_mode(img_path, target_mode='L'):
    with Image.open(img_path) as img:
        if img.mode != target_mode:
            converted = img.convert(target_mode)
            converted.save(img_path, format=img.format or 'PNG')

# Convert all images to L
for img_path in df['path']:
    convert_color_mode(img_path, 'L')

from PIL import Image

def is_valid(img_path):
    try:
        with Image.open(img_path) as img:
            img.verify()
        return True
    except:
        return False

# Remove corrupt images
df = df[df['path'].apply(is_valid)].reset_index(drop=True)
